/// A comment line that opens with a generator's marker: `// GENERATED CODE`,
/// `// Generated by ...`, `//  Generated code. Do not modify.`. Prose that
/// merely mentions generated code, and `///` doc comments, do not count.
final RegExp generatedMarkerPattern = RegExp(
  r'^\s*(?://(?!/)|/\*+|\*)\s*'
  r'(?:GENERATED CODE|Generated code|Generated by|Generated using|DO NOT EDIT)\b',
);
